 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # Each bottom 5 extends a vertical ray upward. Existing nonzero cells
    # change the color carried above them; empty cells receive that color.
    for c in range(len(grid[0])):
        if grid[-1][c] != 5:
            continue
        color = 5
        for r in range(len(grid) - 1, -1, -1):
            if grid[r][c] != 0:
                color = grid[r][c]
            else:
                out[r][c] = color
    return out
